/* ---------- Грамматика для Speaking ---------- */
const GRAMMAR = [
 {t:"Present Perfect — опыт и «до сих пор»", b:7, use:"Part 1 и 2: сколько времени, был ли опыт, что изменилось.", tpl:["I've been … for (+ срок) / since (+ момент)","I've never …, but I'd love to.","It's changed a lot since …"], ex:"I've been living in Kazan for six years, and the city has changed dramatically since I moved here.", err:"✗ I live here since 2019 → ✓ I've lived / I've been living here since 2019."},
 {t:"Used to / would — привычки в прошлом", b:7, use:"Вопросы про детство в Part 1, истории в Part 2, «раньше — сейчас» в Part 3.", tpl:["When I was a kid, I used to …","We would spend hours …","I didn't use to …, but now …"], ex:"When I was a kid, we used to spend every summer at my grandma's, and we'd go swimming in the lake every single day.", err:"✗ I used to playing → ✓ I used to play (used to + V1)."},
 {t:"Условные: 2-й и 3-й тип", b:7, use:"«Would you like…», мечты, сожаления в Part 2, гипотезы в Part 3.", tpl:["If I had more time, I'd …","If I hadn't …, I would never have …","If governments invested more in …, people would …"], ex:"If I hadn't missed that train, I would never have met my best friend.", err:"✗ If I will have time → ✓ If I have time (после if нет will)."},
 {t:"Смешанное условное (band 8)", b:8, use:"Прошлое влияет на настоящее — сильная структура для Part 2.", tpl:["If I'd studied harder at school, I'd be a doctor now.","If I hadn't moved to Moscow, I wouldn't be working here today."], ex:"If I hadn't taken that gap year, I probably wouldn't be so independent now.", err:"Следи за формами: had + V3 в if, would + V1 в главной части."},
 {t:"Относительные придаточные", b:7, use:"Везде: удлиняют предложение естественно, без «and… and…».", tpl:["…, which is …","the person who …","the place where …","my friend, whose …"], ex:"I live in Tver, which is a small city about two hours from Moscow, where most of my friends work.", err:"✗ the place which I was born → ✓ the place where I was born / which I was born in."},
 {t:"Cleft sentences — выделение главного", b:8, use:"Opener и оценка в Part 2: звучит очень естественно.", tpl:["What I love most about it is …","The thing that surprised me was …","It was only when …, that I realised …","What really stands out is …"], ex:"What I love most about my job is that no two days are the same.", err:"✗ What I like is the people is friendly → ✓ What I like is that the people are friendly."},
 {t:"Сравнения", b:7, use:"Part 1 (предпочтения), Part 3 (раньше / сейчас, город / деревня).", tpl:["far / much more … than","not nearly as … as","The more …, the more …","…, whereas …"], ex:"Life in the countryside is far less stressful than in the city, but it's not nearly as convenient.", err:"✗ more better / more easier → ✓ better / easier."},
 {t:"Пассив и безличные конструкции", b:7, use:"Part 3 и описания мест: It's widely believed…, It was built in…", tpl:["It was built in …","It's widely believed that …","Children are often encouraged to …","It's said to be …"], ex:"It's widely believed that the cathedral was built in the 12th century.", err:"✗ It was build → ✓ It was built (be + V3)."},
 {t:"Модальные глаголы предположения", b:7, use:"Part 3: осторожные ответы, когда не знаешь точно.", tpl:["It might be because …","They must have …","It could be that …","People may well …"], ex:"It might be because young people simply have more options these days.", err:"✗ They must to go → ✓ They must go (без to)."},
 {t:"Причастные обороты", b:8, use:"Начало предложения в Part 2 и Part 3 — признак band 8.", tpl:["Having grown up in …, I …","Living in a big city, you …","Looking back, …","Compared to …, …"], ex:"Having grown up by the sea, I find it hard to live anywhere landlocked.", err:"Подлежащее главной части должно быть тем же: ✗ Having grown up there, the city is dear to me."},
 {t:"Wish / if only — сожаления и желания", b:7, use:"Part 2 («чего жаль»), Part 1 (что бы изменил).", tpl:["I wish I had …","I wish I could …","If only I'd …"], ex:"I wish I'd started learning English earlier — it would have saved me so much stress.", err:"✗ I wish I can → ✓ I wish I could."},
 {t:"Будущее и планы", b:7, use:"Part 1 (планы), Part 3 (прогнозы).", tpl:["I'm planning to …","I'm hoping to …","By the time I'm 30, I'll have …","… is likely to / bound to …"], ex:"By the time I graduate, I'll have spent four years abroad.", err:"✗ I will to go → ✓ I'll go / I'm going to go."}
];

